commits.patch:
diff --git a/src/type1/t1parse.c b/src/type1/t1parse.c
index 6947b3daa..36c73fe4d 100644
--- a/src/type1/t1parse.c
+++ b/src/type1/t1parse.c
@@ -284,10 +284,24 @@
         if ( tag != 0x8002U )
           break;

-        if ( FT_QREALLOC( priv_dict, priv_len, priv_len + size ) ||
-             FT_STREAM_READ( priv_dict + priv_len, size )        )
+        if ( FT_QREALLOC( priv_dict, priv_len, priv_len + size ) )
           goto Fail;

+        if ( stream->read )
+        {
+          if ( FT_STREAM_READ( priv_dict + priv_len, size ) )
+            goto Fail;
+        }
+        else
+        {
+          if ( size > stream->size - stream->pos )
+            goto Fail;
+
+          FT_MEM_MOVE( priv_dict + priv_len,
+                       stream->base + stream->pos, size );
+          stream->pos += size;
+        }
+
         priv_len += size;
       }
